// goldenCatalog is a complete, valid `list --json` document.
//
// It is written by hand rather than produced from internal/mutation, because
// this package's job is to police the JSON contract and a golden generated by
// the code under test polices nothing. It exercises the parts of the schema
// that are easy to get wrong: a mutant with an empty replacement — statement
// deletion, which the schema must allow — an empty exclude list, and a skip
// count of more than one.
const goldenCatalog = `{
  "document_type": "go-mutants/catalog",
  "schema_version": 1,
  "tool_version": "0.1.0-dev",
  "workspace": {
    "module_path": "github.com/P4suta/go-mutants",
    "go_version": "go1.26.5",
    "workspace_digest": "07c5a1e94b83d26f0a1b7c8de95243f60b8a17d3e42c9b058f1d6a723c40e9b8",
    "platform": { "os": "linux", "arch": "amd64" }
  },
  "selection": {
    "profile": "balanced",
    "operators": ["comparison", "statement-deletion"],
    "include": ["**/*.go"],
    "exclude": []
  },
  "mutants": [
    {
      "id": "4b2f8c1d0e6a39571c84fb02de7a6519cf3b48d20a71e6c95f803b4d17ea92c6",
      "display_id": "4b2f8c1d0e6a39571c84",
      "path": "internal/mutation/score.go",
      "package": "github.com/P4suta/go-mutants/internal/mutation",
      "family": "comparison",
      "rule": "eq-to-neq",
      "rule_version": 1,
      "line": 88,
      "column": 12,
      "start_byte": 2143,
      "end_byte": 2145,
      "original": "==",
      "replacement": "!="
    },
    {
      "id": "9d10c7e3a5b28f4061ce93d7b085a2f419736c8de0524ab7139fc60a8e5d3b21",
      "display_id": "9d10c7e3a5b28f4061ce",
      "path": "internal/runner/runner.go",
      "package": "github.com/P4suta/go-mutants/internal/runner",
      "family": "statement-deletion",
      "rule": "delete-call-statement",
      "rule_version": 1,
      "line": 214,
      "column": 2,
      "start_byte": 5310,
      "end_byte": 5327,
      "original": "cmd.Stdout = &out",
      "replacement": ""
    }
  ],
  "skips": [
    { "path": "internal/mutation/rule.go", "reason": "const-decl", "count": 4 },
    { "path": "internal/glob/glob.go", "reason": "generated", "count": 1 }
  ]
}`

func TestValidateAcceptsGoldenCatalog(t *testing.T) {
	if err := Validate(CatalogV1, []byte(goldenCatalog)); err != nil {
		t.Fatalf("golden catalog rejected: %v", err)
	}
}

// TestValidateRejects mutates the golden document one field at a time. Each
// case asserts the pointer as well as the code: a schema that rejects the right
// documents for the wrong reason is a schema that will blame the wrong field
// the first time a real document is malformed.
func TestValidateRejects(t *testing.T) {
	tests := []struct {
		name        string
		mutate      func(t *testing.T, doc map[string]any)
		wantPointer string
	}{
		{
			name:        "missing top-level field",
			mutate:      func(_ *testing.T, doc map[string]any) { delete(doc, "skips") },
			wantPointer: "/skips",
		},
		{
			name:        "unexpected top-level field",
			mutate:      func(_ *testing.T, doc map[string]any) { doc["run_id"] = "abc" },
			wantPointer: "/run_id",
		},
		{
			name:        "wrong document type",
			mutate:      func(_ *testing.T, doc map[string]any) { doc["document_type"] = "go-mutants/run-report" },
			wantPointer: "/document_type",
		},
		{
			name:        "wrong schema version",
			mutate:      func(_ *testing.T, doc map[string]any) { doc["schema_version"] = json.Number("2") },
			wantPointer: "/schema_version",
		},
		{
			name:        "empty tool version",
			mutate:      func(_ *testing.T, doc map[string]any) { doc["tool_version"] = "" },
			wantPointer: "/tool_version",
		},
		{
			name: "workspace digest is not 64 hex",
			mutate: func(t *testing.T, doc map[string]any) {
				object(t, doc, "workspace")["workspace_digest"] = "07c5a1e9"
			},
			wantPointer: "/workspace/workspace_digest",
		},
		{
			name: "platform missing arch",
			mutate: func(t *testing.T, doc map[string]any) {
				delete(object(t, object(t, doc, "workspace"), "platform"), "arch")
			},
			wantPointer: "/workspace/platform/arch",
		},
		{
			name: "unknown profile",
			mutate: func(t *testing.T, doc map[string]any) {
				object(t, doc, "selection")["profile"] = "aggressive"
			},
			wantPointer: "/selection/profile",
		},
		{
			name: "include is not an array",
			mutate: func(t *testing.T, doc map[string]any) {
				object(t, doc, "selection")["include"] = "**/*.go"
			},
			wantPointer: "/selection/include",
		},
		{
			name:        "missing mutant field",
			mutate:      func(t *testing.T, doc map[string]any) { delete(mutant(t, doc, 0), "line") },
			wantPointer: "/mutants/0/line",
		},
		{
			name:        "unexpected mutant field",
			mutate:      func(t *testing.T, doc map[string]any) { mutant(t, doc, 0)["outcome"] = "killed" },
			wantPointer: "/mutants/0/outcome",
		},
		{
			name: "id is not lowercase hex",
			mutate: func(t *testing.T, doc map[string]any) {
				m := mutant(t, doc, 0)
				id, ok := m["id"].(string)
				if !ok {
					t.Fatalf("the golden mutant has no string id")
				}
				m["id"] = strings.ToUpper(id)
			},
			wantPointer: "/mutants/0/id",
		},
		{
			name:        "display id is the wrong length",
			mutate:      func(t *testing.T, doc map[string]any) { mutant(t, doc, 1)["display_id"] = "9d10c7e3a5b28f4061" },
			wantPointer: "/mutants/1/display_id",
		},
		{
			name:        "line is zero",
			mutate:      func(t *testing.T, doc map[string]any) { mutant(t, doc, 0)["line"] = json.Number("0") },
			wantPointer: "/mutants/0/line",
		},
		{
			name:        "column is zero",
			mutate:      func(t *testing.T, doc map[string]any) { mutant(t, doc, 1)["column"] = json.Number("0") },
			wantPointer: "/mutants/1/column",
		},
		{
			name:        "rule version is zero",
			mutate:      func(t *testing.T, doc map[string]any) { mutant(t, doc, 0)["rule_version"] = json.Number("0") },
			wantPointer: "/mutants/0/rule_version",
		},
		{
			name:        "start byte is negative",
			mutate:      func(t *testing.T, doc map[string]any) { mutant(t, doc, 0)["start_byte"] = json.Number("-1") },
			wantPointer: "/mutants/0/start_byte",
		},
		{
			name:        "line is not an integer",
			mutate:      func(t *testing.T, doc map[string]any) { mutant(t, doc, 0)["line"] = json.Number("88.5") },
			wantPointer: "/mutants/0/line",
		},
		{
			name:        "original is not a string",
			mutate:      func(t *testing.T, doc map[string]any) { mutant(t, doc, 0)["original"] = json.Number("2") },
			wantPointer: "/mutants/0/original",
		},
		{
			name:        "skip count is zero",
			mutate:      func(t *testing.T, doc map[string]any) { skip(t, doc, 0)["count"] = json.Number("0") },
			wantPointer: "/skips/0/count",
		},
		{
			name:        "skip reason is empty",
			mutate:      func(t *testing.T, doc map[string]any) { skip(t, doc, 1)["reason"] = "" },
			wantPointer: "/skips/1/reason",
		},
		{
			name:        "mutants is not an array",
			mutate:      func(_ *testing.T, doc map[string]any) { doc["mutants"] = map[string]any{} },
			wantPointer: "/mutants",
		},
		{
			name:        "the document is not an object",
			mutate:      nil,
			wantPointer: "",
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			encoded := []byte(`[]`)
			if test.mutate != nil {
				doc := decode(t, goldenCatalog)
				test.mutate(t, doc)
				encoded = encode(t, doc)
			}
			err := Validate(CatalogV1, encoded)
			if err == nil {
				t.Fatalf("mutated document was accepted")
			}
			if got := CodeOf(err); got != CodeInvalidDocument {
				t.Errorf("code = %q, want %q (%v)", got, CodeInvalidDocument, err)
			}
			pointer, ok := PointerOf(err)
			if !ok {
				t.Fatalf("error does not carry a pointer: %v", err)
			}
			if pointer != test.wantPointer {
				t.Errorf("pointer = %q, want %q (%v)", pointer, test.wantPointer, err)
			}
			if !strings.Contains(err.Error(), string(CodeInvalidDocument)) {
				t.Errorf("rendered error does not name its code: %q", err.Error())
			}
			var validationErr *jsonschema.ValidationError
			if !errors.As(err, &validationErr) {
				t.Errorf("error does not wrap the validator's cause: %v", err)
			}
		})
	}
}

// TestValidateAcceptsEmptyReplacement guards the one field pair the schema must
// deliberately leave unconstrained: statement deletion replaces bytes with
// nothing, so an empty replacement is legal — a reflexive minLength on every
// string here would reject a whole operator family.
func TestValidateAcceptsEmptyReplacement(t *testing.T) {
	doc := decode(t, goldenCatalog)
	m := mutant(t, doc, 0)
	m["replacement"] = ""
	if err := Validate(CatalogV1, encode(t, doc)); err != nil {
		t.Fatalf("empty replacement rejected: %v", err)
	}
}

func TestValidateRejectsUnknownDocumentType(t *testing.T) {
	err := Validate("go-mutants/catalogue", []byte(goldenCatalog))
	if err == nil {
		t.Fatal("unknown document type was accepted")
	}
	if got := CodeOf(err); got != CodeUnknownDocument {
		t.Fatalf("code = %q, want %q (%v)", got, CodeUnknownDocument, err)
	}
	var typed *Error
	if !errors.As(err, &typed) {
		t.Fatalf("error is not an *Error: %v", err)
	}
	if typed.DocumentType != "go-mutants/catalogue" {
		t.Errorf("DocumentType = %q, want the requested type", typed.DocumentType)
	}
	if !strings.Contains(err.Error(), CatalogV1) {
		t.Errorf("error does not name the types this build validates: %q", err.Error())
	}
}

func TestValidateRejectsMalformedJSON(t *testing.T) {
	for _, input := range []string{"", "{", `{"document_type": }`, `{} {}`} {
		err := Validate(CatalogV1, []byte(input))
		if err == nil {
			t.Fatalf("%q was accepted as JSON", input)
		}
		if got := CodeOf(err); got != CodeMalformedJSON {
			t.Errorf("%q: code = %q, want %q (%v)", input, got, CodeMalformedJSON, err)
		}
	}
}

// TestFirstViolationIsDeterministic is the regression test for the whole point
// of sorting the leaves. The document below breaks the schema in four
// independent places; the validator's error tree branches in map iteration
// order, so a naive "first cause" walk reports a different field on different
// runs. Repeating the call inside one process is what exercises that: Go
// randomizes map iteration per range statement, not per process.
func TestFirstViolationIsDeterministic(t *testing.T) {
	doc := decode(t, goldenCatalog)
	doc["tool_version"] = ""
	object(t, doc, "selection")["profile"] = "aggressive"
	mutant(t, doc, 0)["line"] = json.Number("0")
	mutant(t, doc, 1)["column"] = json.Number("0")
	skip(t, doc, 0)["count"] = json.Number("0")
	encoded := encode(t, doc)

	first, ok := PointerOf(Validate(CatalogV1, encoded))
	if !ok {
		t.Fatal("multiply invalid document was accepted")
	}
	for i := range 200 {
		pointer, gotOK := PointerOf(Validate(CatalogV1, encoded))
		if !gotOK {
			t.Fatalf("attempt %d: document was accepted", i)
		}
		if pointer != first {
			t.Fatalf("attempt %d: pointer = %q, first attempt reported %q", i, pointer, first)
		}
	}
	if first != "/mutants/0/line" {
		t.Errorf("pointer = %q, want the lexicographically first violation %q", first, "/mutants/0/line")
	}
}

// TestEveryRegisteredSchemaCompiles asserts the forward direction: every
// registry entry names a schema that reads, compiles, and validates.
// [TestEverySchemaIsRegistered] asserts the reverse.
func TestEveryRegisteredSchemaCompiles(t *testing.T) {
	types := DocumentTypes()
	if len(types) != len(registry) {
		t.Fatalf("DocumentTypes returned %d types for %d registry entries", len(types), len(registry))
	}
	for _, documentType := range types {
		file, ok := registry[documentType]
		if !ok {
			t.Fatalf("DocumentTypes returned %q, which is not in the registry", documentType)
		}
		if _, err := schema.FS.ReadFile(file); err != nil {
			t.Errorf("%s: %v", documentType, err)
			continue
		}
		// An empty object is invalid under every go-mutants schema, so the
		// only interesting question is which failure comes back: anything but
		// an unusable schema means the file compiled.
		err := Validate(documentType, []byte(`{}`))
		if got := CodeOf(err); got != CodeInvalidDocument {
			t.Errorf("%s: validating {} gave code %q (%v), want %q", documentType, got, err, CodeInvalidDocument)
		}
	}
}

// TestEverySchemaIsRegistered asserts the reverse direction: every schema
// embedded in [schema.FS] is one this build can validate against.
//
// The claim is assertable because of what that filesystem holds and does not
// hold. `//go:embed *.json` matches this directory's own files and does not
// recurse, so the vendored third-party schemas — the Stryker report schema,
// which go-mutants projects onto and does not define — live under
// schema/stryker/ behind an embed of their own and never appear here. What is
// left is exactly the set go-mutants publishes, and a published schema nothing
// registers is a schema no `--json` output is ever checked against: it would
// ship, be documented, and validate nothing.
func TestEverySchemaIsRegistered(t *testing.T) {
	entries, err := fs.ReadDir(schema.FS, ".")
	if err != nil {
		t.Fatalf("listing the embedded schemas: %v", err)
	}
	files := make([]string, 0, len(entries))
	for _, entry := range entries {
		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") {
			files = append(files, entry.Name())
		}
	}
	if len(files) == 0 {
		t.Fatal("no schema is embedded at all")
	}
	registered := registeredFiles()
	for _, file := range files {
		if !slices.Contains(registered, file) {
			t.Errorf("schema/%s is published and no document type is validated against it; "+
				"add it to the registry in schemas.go", file)
		}
	}
}

// TestDocumentTypesListsTheTraceEvent pins the trace contract into the same
// registry the report and catalogue documents live in.
//
// A trace is never evidence, but it is still a published format somebody
// scripts against, and the registry is what makes a document type checkable
// rather than merely documented. Listing it here is also what puts it in the
// error message an unknown document type produces, so a consumer that mistypes
// the name is told which types this build knows.
func TestDocumentTypesListsTheTraceEvent(t *testing.T) {
	types := DocumentTypes()
	if !slices.Contains(types, TraceEventV1) {
		t.Fatalf("DocumentTypes() = %v, want it to list %q", types, TraceEventV1)
	}
	if !slices.IsSorted(types) {
		t.Errorf("DocumentTypes() = %v, want it sorted", types)
	}
	if got := registry[TraceEventV1]; got != "trace-v1.schema.json" {
		t.Errorf("the registry maps %q onto %q", TraceEventV1, got)
	}
	// One line of a real recording, which is the unit this document type
	// describes: a recording is JSON Lines, so the schema validates a line
	// rather than a file.
	line := []byte(`{"seq":1,"type":"run-start","schema":"gomutants-trace-v1",` +
		`"timestamp":"2026-09-06T12:00:00Z","elapsed_ms":0,` +
		`"start":{"kind":"run","run_id":"20260906T120000Z-1a2b","tool_version":"0.1.0-dev",` +
		`"pid":31337,"root":"/home/dev/project"}}`)
	if err := Validate(TraceEventV1, line); err != nil {
		t.Errorf("a recorded run-start does not satisfy its own schema: %v", err)
	}
}

// TestSchemaIDsMatchTheirFilenames keeps the published identity of a schema
// tied to the path it is published at. Nothing dereferences these URLs, which
// is exactly why nothing but a test would notice them drifting apart.
func TestSchemaIDsMatchTheirFilenames(t *testing.T) {
	for _, file := range registeredFiles() {
		data, err := schema.FS.ReadFile(file)
		if err != nil {
			t.Fatalf("%s: %v", file, err)
		}
		doc, err := jsonschema.UnmarshalJSON(bytes.NewReader(data))
		if err != nil {
			t.Fatalf("%s: %v", file, err)
		}
		if got, want := resourceURL(file, doc), baseURL+file; got != want {
			t.Errorf("%s: $id = %q, want %q", file, got, want)
		}
	}
}

// TestFirstViolationBreaksTiesAtOneLocation is the half of the ordering
// TestFirstViolationIsDeterministic cannot reach.
//
// That test breaks the schema in several places and pins the pointer, which the
// first sort key alone decides. Two schemas can also reject the *same* value —
// a trace event carrying a payload that belongs to another event type is
// rejected once per foreign payload, every one of them at `/type` — and then
// the pointer settles nothing and the reported complaint is whatever the two
// remaining keys pick. Both documents below are ties on the pointer: the first
// is settled by the keyword and the second by the detail, so between them every
// key of the sort decides an answer a caller reads.
//
// The document is the reason to care rather than the sort: "value must be
// 'exec'" and "value must be 'cache'" are two true statements about one line,
// and which of them a run prints has to be a function of the line rather than
// of a map's iteration order.
func TestFirstViolationBreaksTiesAtOneLocation(t *testing.T) {
	const preamble = `"seq":1,"timestamp":"2026-01-01T00:00:00Z","elapsed_ms":0`

	tests := []struct {
		name     string
		document string
		pointer  string
		detail   string
	}{
		{
			// A phase-start whose payload is not an object at all. `$defs/phase`
			// rejects it for its type, and the `not` that keeps a duration off a
			// phase-start rejects it too, because `required` holds vacuously for
			// something that is not an object — two complaints about `/phase`
			// under two different keywords.
			name:     "one value, two keywords",
			document: `{` + preamble + `,"type":"phase-start","phase":"oops"}`,
			pointer:  "/phase",
			detail:   "'not' failed",
		},
		{
			// A note carrying an exec and a cache payload as well. Each foreign
			// payload demands its own event type of `/type`, so both complaints
			// are `const` failures at one location and only the detail tells
			// them apart.
			name: "one value, two constants",
			document: `{` + preamble + `,"type":"note","note":{"kind":"warning"},` +
				`"cache":{"op":"open","result":"opened"},` +
				`"exec":{"kind":"verify","argv":["go"],"exit_code":0}}`,
			pointer: "/type",
			detail:  "value must be 'cache'",
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			// Repeated inside one process on purpose: Go randomizes map
			// iteration per range statement rather than per process, so a tie
			// broken by iteration order shows up here and nowhere else.
			for i := range 100 {
				err := Validate(TraceEventV1, []byte(test.document))
				if err == nil {
					t.Fatalf("attempt %d: the document was accepted", i)
				}
				pointer, ok := PointerOf(err)
				if !ok {
					t.Fatalf("attempt %d: error does not carry a pointer: %v", i, err)
				}
				if pointer != test.pointer {
					t.Fatalf("attempt %d: pointer = %q, want %q (%v)", i, pointer, test.pointer, err)
				}
				if !strings.HasSuffix(err.Error(), ": "+test.detail) {
					t.Fatalf("attempt %d: error = %q, want it to end in %q", i, err.Error(), test.detail)
				}
			}
		})
	}
}

// TestValidateCarriesTheValidatorsComplaint pins the half of the message that
// is not this package's own words.
//
// The pointer says where and the code says what kind; the validator's own line
// is the only part that says what was wrong with the value. A message that
// stopped at "is not valid at /mutants/0/line:" would read like a finished
// sentence and tell a reader nothing.
func TestValidateCarriesTheValidatorsComplaint(t *testing.T) {
	doc := decode(t, goldenCatalog)
	mutant(t, doc, 0)["line"] = json.Number("0")
	err := Validate(CatalogV1, encode(t, doc))
	if err == nil {
		t.Fatal("mutated document was accepted")
	}
	if !strings.HasSuffix(err.Error(), ": minimum: got 0, want 1") {
		t.Errorf("error = %q, want it to end in the validator's own complaint", err.Error())
	}
}

// TestResourceURL covers the naming rule from both sides, which no embedded
// schema can.
//
// Every schema in this repository declares an "$id" that is exactly the
// fallback this function would otherwise derive — TestSchemaIDsMatchTheirFilenames
// requires it — so compiling them exercises the rule without ever telling the
// two branches apart. A vendored third-party schema is the case the branches
// exist for, and it arrives with an "$id" of its own or with none at all.
func TestResourceURL(t *testing.T) {
	const file = "vendored.schema.json"

	tests := []struct {
		name string
		doc  any
		want string
	}{
		{
			name: "a schema that declares an id keeps it",
			doc:  map[string]any{"$id": "https://stryker-mutator.io/schema/mutation-testing-report.json"},
			want: "https://stryker-mutator.io/schema/mutation-testing-report.json",
		},
		{
			name: "a schema with no id is named after its file",
			doc:  map[string]any{"type": "object"},
			want: baseURL + file,
		},
		{
			name: "an empty id is no id",
			doc:  map[string]any{"$id": ""},
			want: baseURL + file,
		},
		{
			name: "an id that is not a string is no id",
			doc:  map[string]any{"$id": float64(1)},
			want: baseURL + file,
		},
		{
			// The boolean schemas of 2020-12: `true` and `false` are documents,
			// and neither is an object with an "$id" in it.
			name: "a schema that is not an object at all",
			doc:  true,
			want: baseURL + file,
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			if got := resourceURL(file, test.doc); got != test.want {
				t.Errorf("resourceURL = %q, want %q", got, test.want)
			}
		})
	}
}

// TestUnusableNamesTheFileAndKeepsTheCause pins the error every failure inside
// compileAll is reported as.
//
// It is unreachable through [Validate] in a build whose embedded schemas
// compile, which is every build TestEveryRegisteredSchemaCompiles passes on —
// and it is the error a reader will be looking at on the day one does not, so
// it has to name the file and keep what went wrong with it.
func TestUnusableNamesTheFileAndKeepsTheCause(t *testing.T) {
	cause := errors.New("unexpected end of JSON input")
	err := unusable("catalog-v1.schema.json", "is not JSON", cause)
	if err == nil {
		t.Fatal("an unusable schema was reported as usable")
	}
	if got := CodeOf(err); got != CodeSchemaUnusable {
		t.Errorf("code = %q, want %q (%v)", got, CodeSchemaUnusable, err)
	}
	if !errors.Is(err, cause) {
		t.Errorf("the cause is not reachable through the error: %v", err)
	}
	for _, want := range []string{"catalog-v1.schema.json", "is not JSON", cause.Error()} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("error %q does not mention %q", err.Error(), want)
		}
	}
}

// TestInvalidDocumentReportsACauseItCannotWalk covers the branch that exists
// because an error is a poor place to assume anything.
//
// The validator returns *jsonschema.ValidationError and nothing else today, so
// this branch is dead until the day it is not — and on that day it is the
// difference between a caller seeing the failure whole and seeing nothing at
// all, because the alternative to reporting an unrecognised cause is walking a
// tree that is not there.
func TestInvalidDocumentReportsACauseItCannotWalk(t *testing.T) {
	cause := errors.New("the validator returned something else")
	err := invalidDocument(CatalogV1, cause)
	if err == nil {
		t.Fatal("a cause that is not a ValidationError was reported as valid")
	}
	if got := CodeOf(err); got != CodeInvalidDocument {
		t.Errorf("code = %q, want %q (%v)", got, CodeInvalidDocument, err)
	}
	if !errors.Is(err, cause) {
		t.Errorf("the cause is not reachable through the error: %v", err)
	}
	pointer, ok := PointerOf(err)
	if !ok || pointer != "" {
		t.Errorf("pointer = %q, %t; want the empty pointer of a failure with no location", pointer, ok)
	}
	if !strings.Contains(err.Error(), cause.Error()) {
		t.Errorf("error %q does not carry the cause's own words", err.Error())
	}
}

// TestFirstNameOfNoNames pins the answer for a set the validator does not
// produce.
//
// kind.Required and kind.AdditionalProperties always name at least one
// property, so describe never asks this about an empty set — and if one ever
// arrived, the other answer would append an empty token to the pointer and
// report the violation at a property called "".
func TestFirstNameOfNoNames(t *testing.T) {
	if name, ok := firstName(nil); ok || name != "" {
		t.Errorf("firstName(nil) = %q, %t; want the empty name and false", name, ok)
	}
	if name, ok := firstName([]string{"line", "column"}); !ok || name != "column" {
		t.Errorf("firstName = %q, %t; want the lexicographically first name", name, ok)
	}
}

// TestCodeStringIsTheCodeItself pins the one thing a Code renders as.
//
// It is a defined string type, so `%s` and `string(c)` agree with String()
// whatever String() does — which is why the method needs a test of its own: a
// caller printing a code through the fmt.Stringer interface reads this and
// nothing else.
func TestCodeStringIsTheCodeItself(t *testing.T) {
	for _, code := range Codes() {
		if got := code.String(); got != string(code) {
			t.Errorf("%q.String() = %q, want the code itself", string(code), got)
		}
	}
	if got := CodeInvalidDocument.String(); got != "GOM5003" {
		t.Errorf("CodeInvalidDocument.String() = %q, want %q", got, "GOM5003")
	}
}

func TestCodesAreUniqueAndInBlock(t *testing.T) {
	seen := make(map[Code]bool, len(Codes()))
	for _, code := range Codes() {
		if seen[code] {
			t.Errorf("duplicate code %q", code)
		}
		seen[code] = true
		if !strings.HasPrefix(string(code), "GOM50") || len(code) != len("GOM0000") {
			t.Errorf("%q is outside the GOM50xx block this package owns", code)
		}
	}
	if !seen[CodeUnknownDocument] || !seen[CodeMalformedJSON] || !seen[CodeInvalidDocument] || !seen[CodeSchemaUnusable] {
		t.Error("Codes() does not list every code the package defines")
	}
}

// TestErrorRendersOneLine protects the contract internal/cli's error renderer
// depends on: a leading "GOM####: " on a single line.
func TestErrorRendersOneLine(t *testing.T) {
	doc := decode(t, goldenCatalog)
	delete(mutant(t, doc, 0), "line")
	err := Validate(CatalogV1, encode(t, doc))
	if err == nil {
		t.Fatal("mutated document was accepted")
	}
	text := err.Error()
	if strings.Contains(text, "\n") {
		t.Errorf("rendered error spans several lines:\n%s", text)
	}
	if !strings.HasPrefix(text, string(CodeInvalidDocument)+": ") {
		t.Errorf("rendered error does not start with its code: %q", text)
	}
	if !strings.Contains(text, "/mutants/0/line") {
		t.Errorf("rendered error does not name the pointer: %q", text)
	}
	// The validator prints its own "at '<location>':" in front of every
	// complaint. The pointer is reported separately and more precisely, so that
	// prefix is stripped; if it comes back, the message names two locations and
	// the less useful one comes first.
	if strings.Contains(text, "at '/mutants/0'") {
		t.Errorf("rendered error repeats the validator's location prefix: %q", text)
	}
}

func TestPointerOfForeignError(t *testing.T) {
	if _, ok := PointerOf(errors.New("not ours")); ok {
		t.Error("PointerOf claimed a foreign error")
	}
	if got := CodeOf(errors.New("not ours")); got != "" {
		t.Errorf("CodeOf(foreign) = %q, want the empty code", got)
	}
}

func TestDisplayPointerNamesTheRoot(t *testing.T) {
	if got := displayPointer(""); got != "the document root" {
		t.Errorf("displayPointer(\"\") = %q", got)
	}
	if got := displayPointer("/mutants/0"); got != "/mutants/0" {
		t.Errorf("displayPointer = %q", got)
	}
}

func TestEscapeToken(t *testing.T) {
	// RFC 6901 order: '~' is escaped before '/', so "a/~b" becomes "a~1~0b"
	// and never "a~1~01b".
	if got, want := escapeToken("a/~b"), "a~1~0b"; got != want {
		t.Errorf("escapeToken = %q, want %q", got, want)
	}
	if got, want := jsonPointer([]string{"mutants", "0", "a/b"}), "/mutants/0/a~1b"; got != want {
		t.Errorf("jsonPointer = %q, want %q", got, want)
	}
	if got := jsonPointer(nil); got != "" {
		t.Errorf("jsonPointer(nil) = %q, want the empty pointer", got)
	}
}

// decode reads a document into a mutable tree, keeping numbers as
// [json.Number] so that re-encoding cannot turn 88 into 88.0.
//
// internal/testkit/mutantkit offers the same pair, and this is the one place
// that cannot use them: mutantkit imports this package to validate a report, so
// a test in `package schemas` that imported mutantkit would be an import cycle.
// The tests here reach for unexported names — displayPointer, escapeToken,
// jsonPointer — so they cannot move to an external test package either. The copy
// is deliberate, and it is the only one left.
func decode(t *testing.T, document string) map[string]any {
	t.Helper()
	doc, err := jsonschema.UnmarshalJSON(strings.NewReader(document))
	if err != nil {
		t.Fatalf("decoding the golden document: %v", err)
	}
	root, ok := doc.(map[string]any)
	if !ok {
		t.Fatalf("the golden document is not a JSON object")
	}
	return root
}

func encode(t *testing.T, doc map[string]any) []byte {
	t.Helper()
	encoded, err := json.Marshal(doc)
	if err != nil {
		t.Fatalf("encoding the mutated document: %v", err)
	}
	return encoded
}

func object(t *testing.T, doc map[string]any, key string) map[string]any {
	t.Helper()
	value, ok := doc[key].(map[string]any)
	if !ok {
		t.Fatalf("%q is not an object", key)
	}
	return value
}

func element(t *testing.T, doc map[string]any, key string, index int) map[string]any {
	t.Helper()
	array, ok := doc[key].([]any)
	if !ok {
		t.Fatalf("%q is not an array", key)
	}
	if index >= len(array) {
		t.Fatalf("%q has %d elements, wanted index %d", key, len(array), index)
	}
	value, ok := array[index].(map[string]any)
	if !ok {
		t.Fatalf("%s[%d] is not an object", key, index)
	}
	return value
}

func mutant(t *testing.T, doc map[string]any, index int) map[string]any {
	t.Helper()
	return element(t, doc, "mutants", index)
}

func skip(t *testing.T, doc map[string]any, index int) map[string]any {
	t.Helper()
	return element(t, doc, "skips", index)
}
